cc->convert = rgb2bgr;
else if (ds == default_cmyk)
cc->convert = bgr2cmyk;
else
cc->convert = std_conv_color;
}
else if (ss == default_cmyk)
{
if (ds == default_gray)
cc->convert = cmyk2g;
else if (ds == default_rgb)
cc->convert = cmyk2rgb;
else if (ds == default_bgr)
cc->convert = cmyk2bgr;
else
cc->convert = std_conv_color;
}
else if ((ss == fz_device_rgb(ctx) && ds == fz_device_bgr(ctx)) ||
