void Initialized(mojo::ScopedSharedBufferHandle shared_buffer,
mojo::ScopedHandle socket_handle,
bool initially_muted) {
ASSERT_TRUE(shared_buffer.is_valid());
ASSERT_TRUE(socket_handle.is_valid());
base::PlatformFile fd;
mojo::UnwrapPlatformFile(std::move(socket_handle), &fd);
socket_ = std::make_unique<base::CancelableSyncSocket>(fd);
EXPECT_NE(socket_->handle(), base::CancelableSyncSocket::kInvalidHandle);
size_t memory_length;
base::SharedMemoryHandle shmem_handle;
bool read_only;
EXPECT_EQ(
mojo::UnwrapSharedMemoryHandle(std::move(shared_buffer), &shmem_handle,
&memory_length, &read_only),
MOJO_RESULT_OK);
EXPECT_TRUE(read_only);
buffer_ = std::make_unique<base::SharedMemory>(shmem_handle, read_only);
GotNotification(initially_muted);
}

void TabHelper::OnReenableComplete(int install_id,
int return_route_id,
ExtensionReenabler::ReenableResult result) {
extension_reenabler_.reset();
webstore_install::Result webstore_result = webstore_install::SUCCESS;
std::string error;
switch (result) {
case ExtensionReenabler::REENABLE_SUCCESS:
break;
case ExtensionReenabler::USER_CANCELED:
webstore_result = webstore_install::USER_CANCELLED;
error = "User canceled install.";
break;
case ExtensionReenabler::NOT_ALLOWED:
webstore_result = webstore_install::NOT_PERMITTED;
error = "Install not permitted.";
break;
case ExtensionReenabler::ABORTED:
webstore_result = webstore_install::ABORTED;
error = "Aborted due to tab closing.";
break;
}
OnInlineInstallComplete(install_id,
return_route_id,
result == ExtensionReenabler::REENABLE_SUCCESS,
error,
webstore_result);
}

