            // If index filename has not been specfied, look in BAM folder
            if (fn_idx != NULL)  {
                idx = sam_index_load2(data[i]->fp, fn[i], fn_idx[i]);
            } else {
                idx = sam_index_load(data[i]->fp, fn[i]);
            }

            if (idx == NULL) {
                fprintf(stderr, "[%s] fail to load index for %s\n", __func__, fn[i]);
                exit(EXIT_FAILURE);
            }
            if ( (data[i]->iter=sam_itr_querys(idx, h_tmp, conf->reg)) == 0) {
                fprintf(stderr, "[E::%s] fail to parse region '%s' with %s\n", __func__, conf->reg, fn[i]);
                exit(EXIT_FAILURE);
            }
            if (i == 0) beg0 = data[i]->iter->beg, end0 = data[i]->iter->end, tid0 = data[i]->iter->tid;
            hts_idx_destroy(idx);
        }
        else
            data[i]->iter = NULL;

        if (i == 0) h = data[i]->h = h_tmp; // save the header of the first file
        else {
            // FIXME: check consistency between h and h_tmp
            sam_hdr_destroy(h_tmp);

            // we store only the first file's header; it's (alleged to be)
            // compatible with the i-th file's target_name lookup needs
            data[i]->h = h;
        }
    }
    fprintf(stderr, "[%s] %d samples in %d input files\n",
            __func__, sm->n, nfn);

    pileup_fp = conf->output_fname? fopen(conf->output_fname, "w") : stdout;

    if (pileup_fp == NULL) {
        fprintf(stderr, "[%s] failed to write to %s: %s\n", __func__, conf->output_fname, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // init pileup
    iter = bam_mplp_init(nfn, mplp_func, (void**)data);
    if (conf->flag & MPLP_PRINT_MODS) {
        bam_mplp_constructor(iter, pileup_cd_create);
        bam_mplp_destructor(iter, pileup_cd_destroy);
    }
    if ( conf->flag & MPLP_SMART_OVERLAPS ) bam_mplp_init_overlaps(iter);
    if ( !conf->max_depth ) {
        max_depth = INT_MAX;
        fprintf(stderr, "[%s] Max depth set to maximum value (%d)\n", __func__, INT_MAX);
    } else {
        max_depth = conf->max_depth;
        if ( max_depth * nfn > 1<<20 )
            fprintf(stderr, "[%s] Combined max depth is above 1M. Potential memory hog!\n", __func__);
    }


    bam_mplp_set_maxcnt(iter, max_depth);
    int ret;
    int last_tid = -1;
    hts_pos_t last_pos = -1;
    int one_seq = 0;

    // begin pileup
    kstring_t ks_seq = KS_INITIALIZE;
    kstring_t ks_mod = KS_INITIALIZE;
    kstring_t ks_qual = KS_INITIALIZE;
    while ( (ret=bam_mplp64_auto(iter, &tid, &pos, n_plp, plp)) > 0) {
        one_seq = 1; // at least 1 output
        if (conf->reg && (pos < beg0 || pos >= end0)) continue; // out of the region requested
        if (conf->all) {
            // Deal with missing portions of previous tids
            while (tid > last_tid) {
                if (last_tid >= 0 && !conf->reg) {
                    while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                        if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0)
                            continue;
                        print_empty_pileup(pileup_fp, conf, sam_hdr_tid2name(h, last_tid), last_pos, nfn, ref, ref_len);
                    }
                }
                last_tid++;
                last_pos = -1;
                if (conf->all < 2)
                    break;
                if (tid > last_tid)
                    // multiple missing references and -aa used
                    mplp_get_ref(data[0], last_tid, &ref, &ref_len);
            }
        }
        mplp_get_ref(data[0], tid, &ref, &ref_len);

        if (conf->all) {
            // Deal with missing portion of current tid
            while (++last_pos < pos) {
                if (conf->reg && last_pos < beg0) continue; // out of range; skip
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), last_pos, last_pos + 1) == 0)
                    continue;
                print_empty_pileup(pileup_fp, conf, sam_hdr_tid2name(h, tid), last_pos, nfn, ref, ref_len);
            }
            last_tid = tid;
            last_pos = pos;
        }
        if (conf->bed && tid >= 0 && !bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), pos, pos+1)) continue;

        fprintf(pileup_fp, "%s\t%"PRIhts_pos"\t%c", sam_hdr_tid2name(h, tid), pos + 1, (ref && pos < ref_len)? ref[pos] : 'N');
        for (i = 0; i < nfn; ++i) {
            int j, cnt, err = 0;
            ks_clear(&ks_seq);
            ks_clear(&ks_qual);
            ks_clear(&ks_mod);
            for (j = cnt = 0; j < n_plp[i]; ++j) {
                const bam_pileup1_t *p = plp[i] + j;
                int c = p->qpos < p->b->core.l_qseq
                    ? bam_get_qual(p->b)[p->qpos]
                    : 0;
                if (c >= conf->min_baseQ) {
                    // Build up seq
                    err |= pileup_seq(&ks_seq, plp[i] + j, pos, ref_len,
                                      ref, &ks_mod, conf->rev_del,
                                      conf->no_ins, conf->no_ins_mods,
                                      conf->no_del, conf->no_ends) < 0;

                    // Build up qual
                    err |= kputc_(c+33 < 126 ? c+33 : 126, &ks_qual) < 0;
                    cnt++;
                }
            }
            if (err) {
                ret = 1;
                goto fail;
            }
            fprintf(pileup_fp, "\t%d\t", cnt);

            if (n_plp[i] == 0) {
                fputs("*\t*", pileup_fp);
                int flag_value = MPLP_PRINT_MAPQ_CHAR;
                while(flag_value < MPLP_PRINT_LAST) {
                    if (flag_value != MPLP_PRINT_MODS
                        && (conf->flag & flag_value))
                        fputs("\t*", pileup_fp);
                    flag_value <<= 1;
                }
                if (conf->auxlist) {
                    int t = 0;
                    while(t++ < ((klist_t(auxlist) *)conf->auxlist)->size)
                        fputs("\t*", pileup_fp);
                }
            } else {
                if (ks_seq.l) {
                    fwrite(ks_seq.s, 1, ks_seq.l, pileup_fp);
                } else {
                    putc('*', pileup_fp);
                }
                putc('\t', pileup_fp);

                if (ks_qual.l) {
                    fwrite(ks_qual.s, 1, ks_qual.l, pileup_fp);
                } else {
                    putc('*', pileup_fp);
                }

                /* Print selected columns */
                int flag_value = MPLP_PRINT_MAPQ_CHAR;
                while(flag_value < MPLP_PRINT_LAST) {
                    if (flag_value != MPLP_PRINT_MODS
                        && (conf->flag & flag_value)) {
                        int n = 0;
                        putc('\t', pileup_fp);
                        for (j = 0; j < n_plp[i]; ++j) {
                            const bam_pileup1_t *p = &plp[i][j];
                            int c = p->qpos < p->b->core.l_qseq
                                ? bam_get_qual(p->b)[p->qpos]
                                : 0;
                            if ( c < conf->min_baseQ ) continue;
                            if (n > 0 && flag_value != MPLP_PRINT_MAPQ_CHAR) putc(',', pileup_fp);
                            n++;

                            switch (flag_value) {
                            case MPLP_PRINT_MAPQ_CHAR:
                                c = p->b->core.qual + 33;
                                if (c > 126) c = 126;
                                putc(c, pileup_fp);
                                break;
                            case MPLP_PRINT_QPOS:
                                // query position in current orientation
                                fprintf(pileup_fp, "%d", p->qpos + 1);
                                break;
                            case MPLP_PRINT_QPOS5: {
                                // query position in 5' to 3' orientation
                                int pos5 = bam_is_rev(p->b)
                                    ? p->b->core.l_qseq-p->qpos + p->is_del
                                    : p->qpos + 1;
                                fprintf(pileup_fp, "%d", pos5);
                                break;
                            }
                            case MPLP_PRINT_QNAME:
                                fputs(bam_get_qname(p->b), pileup_fp);
                                break;
                            case MPLP_PRINT_FLAG:
                                fprintf(pileup_fp, "%d", p->b->core.flag);
                                break;
                            case MPLP_PRINT_RNAME:
                                if (p->b->core.tid >= 0)
                                    fputs(sam_hdr_tid2name(h, p->b->core.tid), pileup_fp);
                                else
                                    putc('*', pileup_fp);
                                break;
                            case MPLP_PRINT_POS:
                                fprintf(pileup_fp, "%"PRId64, (int64_t) p->b->core.pos + 1);
                                break;
                            case MPLP_PRINT_MAPQ:
                                fprintf(pileup_fp, "%d", p->b->core.qual);
                                break;
                            case MPLP_PRINT_RNEXT:
                                if (p->b->core.mtid >= 0)
                                    fputs(sam_hdr_tid2name(h, p->b->core.mtid), pileup_fp);
                                else
                                    putc('*', pileup_fp);
                                break;
                            case MPLP_PRINT_PNEXT:
                                fprintf(pileup_fp, "%"PRId64, (int64_t) p->b->core.mpos + 1);
                                break;
                            case MPLP_PRINT_RLEN:
                                fprintf(pileup_fp, "%d", p->b->core.l_qseq);
                                break;
                            }
                        }
                        if (!n) putc('*', pileup_fp);
                    }
                    flag_value <<= 1;
                }

                /* Print selected tags */
                klist_t(auxlist) *auxlist_p = ((klist_t(auxlist) *)conf->auxlist);
                if (auxlist_p && auxlist_p->size) {
                    kliter_t(auxlist) *aux;
                    for (aux = kl_begin(auxlist_p); aux != kl_end(auxlist_p); aux = kl_next(aux)) {
                        int n = 0; // NB shadows outer loop
                        putc('\t', pileup_fp);
                        for (j = 0; j < n_plp[i]; ++j) {
                            const bam_pileup1_t *p = &plp[i][j];
                            int c = p->qpos < p->b->core.l_qseq
                                ? bam_get_qual(p->b)[p->qpos]
                                : 0;
                            if ( c < conf->min_baseQ ) continue;

                            if (n > 0) putc(conf->sep, pileup_fp);
                            n++;
                            uint8_t* tag_u = bam_aux_get(p->b, kl_val(aux));
                            if (!tag_u) {
                                putc(conf->empty , pileup_fp);
                                continue;
                            }

                            int tag_supported = 0;

                            /* Tag value is string */
                            if (*tag_u == 'Z' || *tag_u == 'H') {
                                char *tag_s = bam_aux2Z(tag_u);
                                if (!tag_s) continue;
                                fputs(tag_s, pileup_fp);
                                tag_supported = 1;
                            }

                            /* Tag value is integer */
                            if (*tag_u == 'I' || *tag_u == 'i' || *tag_u == 'C' || *tag_u == 'c' || *tag_u == 'S' || *tag_u == 's') {
                                int64_t tag_i = bam_aux2i(tag_u);
                                fprintf(pileup_fp, "%" PRId64 "", tag_i);
                                tag_supported = 1;
                            }

                            /* Tag value is float */
                            if (*tag_u == 'd' || *tag_u == 'f') {
                                double tag_f = bam_aux2f(tag_u);
                                fprintf(pileup_fp, "%lf", tag_f);
                                tag_supported = 1;
                            }

                            /* Tag value is character */
                            if (*tag_u == 'A') {
                                char tag_c = bam_aux2A(tag_u);
                                putc(tag_c, pileup_fp);
                                tag_supported = 1;
                            }

                            if (!tag_supported) putc('*', pileup_fp);
                        }
                        if (!n) putc('*', pileup_fp);
                    }
                }
            }
        }
        putc('\n', pileup_fp);
    }

    ks_free(&ks_seq);
    ks_free(&ks_mod);
    ks_free(&ks_qual);

    if (ret < 0) {
        print_error("mpileup", "error reading from input file");
        ret = EXIT_FAILURE;
        goto fail;
    }

    if (conf->all) {
        // Handle terminating region
        if (last_tid < 0 && conf->reg && conf->all > 1) {
            last_tid = tid0;
            last_pos = beg0-1;
            mplp_get_ref(data[0], tid0, &ref, &ref_len);
        } else if (last_tid < 0 && !one_seq && conf->all > 1) {
            last_tid = 0; // --aa on a blank file
        }
        while (last_tid >= 0 && last_tid < sam_hdr_nref(h)) {
            mplp_get_ref(data[0], last_tid, &ref, &ref_len);
            while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                if (last_pos >= end0) break;
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0)
                    continue;
                print_empty_pileup(pileup_fp, conf, sam_hdr_tid2name(h, last_tid), last_pos, nfn, ref, ref_len);
            }
            last_tid++;
            last_pos = -1;
            if (conf->all < 2 || conf->reg)
                break;
        }
    }

fail:
    // clean up
    if (pileup_fp && conf->output_fname) fclose(pileup_fp);
    bam_smpl_destroy(sm); free(buf.s);
    for (i = 0; i < gplp.n; ++i) free(gplp.plp[i]);
    free(gplp.plp); free(gplp.n_plp); free(gplp.m_plp);
    bam_mplp_destroy(iter);
    sam_hdr_destroy(h);
    for (i = 0; i < nfn; ++i) {
        sam_close(data[i]->fp);
        if (data[i]->iter) hts_itr_destroy(data[i]->iter);
        free(data[i]);
    }
    free(data); free(plp); free(n_plp);
    free(mp_ref.ref[0]);
    free(mp_ref.ref[1]);
    return ret;
}

static int mpileup(mplp_conf_t *conf, int nfn, char **fn, char **fn_idx)
{
    mplp_aux_t **data;
    int i, tid, *n_plp, tid0 = 0, max_depth;
    hts_pos_t pos, beg0 = 0, end0 = HTS_POS_MAX, ref_len;
    const bam_pileup1_t **plp;
    mplp_ref_t mp_ref = MPLP_REF_INIT;
    bam_mplp_t iter;
    sam_hdr_t *h = NULL; /* header of first file in input list */
    char *ref;
    FILE *pileup_fp = NULL;

    bam_sample_t *sm = NULL;
    kstring_t buf;
    mplp_pileup_t gplp;

    memset(&gplp, 0, sizeof(mplp_pileup_t));
    memset(&buf, 0, sizeof(kstring_t));
    data = calloc(nfn, sizeof(mplp_aux_t*));
    plp = calloc(nfn, sizeof(bam_pileup1_t*));
    n_plp = calloc(nfn, sizeof(int));
    sm = bam_smpl_init();

    if (nfn == 0) {
        fprintf(stderr,"[%s] no input file/data given\n", __func__);
        exit(EXIT_FAILURE);
    }

    // read the header of each file in the list and initialize data
    refs_t *refs = NULL;
    for (i = 0; i < nfn; ++i) {
        sam_hdr_t *h_tmp;
        data[i] = calloc(1, sizeof(mplp_aux_t));
        data[i]->fp = sam_open_format(fn[i], "rb", &conf->ga.in);
        if ( !data[i]->fp )
        {
            fprintf(stderr, "[%s] failed to open %s: %s\n", __func__, fn[i], strerror(errno));
            exit(EXIT_FAILURE);
        }
        if (hts_set_opt(data[i]->fp, CRAM_OPT_DECODE_MD, 0)) {
            fprintf(stderr, "Failed to set CRAM_OPT_DECODE_MD value\n");
            exit(EXIT_FAILURE);
        }

        if (!refs && conf->fai_fname) {
            if (hts_set_fai_filename(data[i]->fp, conf->fai_fname) != 0) {
                fprintf(stderr, "[%s] failed to process %s: %s\n",
                        __func__, conf->fai_fname, strerror(errno));
                exit(EXIT_FAILURE);
            }
            refs = cram_get_refs(data[i]->fp);
        } else if (conf->fai_fname) {
            if (hts_set_opt(data[i]->fp, CRAM_OPT_SHARED_REF, refs) != 0) {
                fprintf(stderr, "[%s] failed to process %s: %s\n",
                        __func__, conf->fai_fname, strerror(errno));
                exit(EXIT_FAILURE);
            }
        }

        data[i]->conf = conf;
        data[i]->ref = &mp_ref;
        h_tmp = sam_hdr_read(data[i]->fp);
        if ( !h_tmp ) {
            fprintf(stderr,"[%s] fail to read the header of %s\n", __func__, fn[i]);
            exit(EXIT_FAILURE);
        }
        bam_smpl_add(sm, fn[i], (conf->flag&MPLP_IGNORE_RG)? 0 : sam_hdr_str(h_tmp));
        if (conf->reg) {
            hts_idx_t *idx = NULL;
            // If index filename has not been specfied, look in BAM folder
            if (fn_idx != NULL)  {
                idx = sam_index_load2(data[i]->fp, fn[i], fn_idx[i]);
            } else {
                idx = sam_index_load(data[i]->fp, fn[i]);
            }

            if (idx == NULL) {
                fprintf(stderr, "[%s] fail to load index for %s\n", __func__, fn[i]);
                exit(EXIT_FAILURE);
            }
            if ( (data[i]->iter=sam_itr_querys(idx, h_tmp, conf->reg)) == 0) {
                fprintf(stderr, "[E::%s] fail to parse region '%s' with %s\n", __func__, conf->reg, fn[i]);
                exit(EXIT_FAILURE);
            }
            if (i == 0) beg0 = data[i]->iter->beg, end0 = data[i]->iter->end, tid0 = data[i]->iter->tid;
            hts_idx_destroy(idx);
        }
        else
            data[i]->iter = NULL;

        if (i == 0) h = data[i]->h = h_tmp; // save the header of the first file
        else {
            // FIXME: check consistency between h and h_tmp
            sam_hdr_destroy(h_tmp);

            // we store only the first file's header; it's (alleged to be)
            // compatible with the i-th file's target_name lookup needs
            data[i]->h = h;
        }
    }
    fprintf(stderr, "[%s] %d samples in %d input files\n",
            __func__, sm->n, nfn);

    pileup_fp = conf->output_fname? fopen(conf->output_fname, "w") : stdout;

    if (pileup_fp == NULL) {
        fprintf(stderr, "[%s] failed to write to %s: %s\n", __func__, conf->output_fname, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // init pileup
    iter = bam_mplp_init(nfn, mplp_func, (void**)data);
    if (conf->flag & MPLP_PRINT_MODS) {
        bam_mplp_constructor(iter, pileup_cd_create);
        bam_mplp_destructor(iter, pileup_cd_destroy);
    }
    if ( conf->flag & MPLP_SMART_OVERLAPS ) bam_mplp_init_overlaps(iter);
    if ( !conf->max_depth ) {
        max_depth = INT_MAX;
        fprintf(stderr, "[%s] Max depth set to maximum value (%d)\n", __func__, INT_MAX);
    } else {
        max_depth = conf->max_depth;
        if ( max_depth * nfn > 1<<20 )
            fprintf(stderr, "[%s] Combined max depth is above 1M. Potential memory hog!\n", __func__);
    }


    bam_mplp_set_maxcnt(iter, max_depth);
    int ret;
    int last_tid = -1;
    hts_pos_t last_pos = -1;
    int one_seq = 0;

    // begin pileup
    kstring_t ks_seq = KS_INITIALIZE;
    kstring_t ks_mod = KS_INITIALIZE;
    kstring_t ks_qual = KS_INITIALIZE;
    while ( (ret=bam_mplp64_auto(iter, &tid, &pos, n_plp, plp)) > 0) {
        one_seq = 1; // at least 1 output
        if (conf->reg && (pos < beg0 || pos >= end0)) continue; // out of the region requested
        if (conf->all) {
            // Deal with missing portions of previous tids
            while (tid > last_tid) {
                if (last_tid >= 0 && !conf->reg) {
                    while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                        if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0)
                            continue;
                        print_empty_pileup(pileup_fp, conf, sam_hdr_tid2name(h, last_tid), last_pos, nfn, ref, ref_len);
                    }
                }
                last_tid++;
                last_pos = -1;
                if (conf->all < 2)
                    break;
                if (tid > last_tid)
                    // multiple missing references and -aa used
                    mplp_get_ref(data[0], last_tid, &ref, &ref_len);
            }
        }
        mplp_get_ref(data[0], tid, &ref, &ref_len);

        if (conf->all) {
            // Deal with missing portion of current tid
            while (++last_pos < pos) {
                if (conf->reg && last_pos < beg0) continue; // out of range; skip
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), last_pos, last_pos + 1) == 0)
                    continue;
                print_empty_pileup(pileup_fp, conf, sam_hdr_tid2name(h, tid), last_pos, nfn, ref, ref_len);
            }
            last_tid = tid;
            last_pos = pos;
        }
        if (conf->bed && tid >= 0 && !bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), pos, pos+1)) continue;

        fprintf(pileup_fp, "%s\t%"PRIhts_pos"\t%c", sam_hdr_tid2name(h, tid), pos + 1, (ref && pos < ref_len)? ref[pos] : 'N');
        for (i = 0; i < nfn; ++i) {
            int j, cnt, err = 0;
            ks_clear(&ks_seq);
            ks_clear(&ks_qual);
            ks_clear(&ks_mod);
            for (j = cnt = 0; j < n_plp[i]; ++j) {
                const bam_pileup1_t *p = plp[i] + j;
                int c = p->qpos < p->b->core.l_qseq
                    ? bam_get_qual(p->b)[p->qpos]
                    : 0;
                if (c >= conf->min_baseQ) {
                    // Build up seq
                    err |= pileup_seq(&ks_seq, plp[i] + j, pos, ref_len,
                                      ref, &ks_mod, conf->rev_del,
                                      conf->no_ins, conf->no_ins_mods,
                                      conf->no_del, conf->no_ends) < 0;

                    // Build up qual
                    err |= kputc_(c+33 < 126 ? c+33 : 126, &ks_qual) < 0;
                    cnt++;
                }
            }
            if (err) {
                ret = 1;
                goto fail;
            }
            fprintf(pileup_fp, "\t%d\t", cnt);

            if (n_plp[i] == 0) {
                fputs("*\t*", pileup_fp);
                int flag_value = MPLP_PRINT_MAPQ_CHAR;
                while(flag_value < MPLP_PRINT_LAST) {
                    if (flag_value != MPLP_PRINT_MODS
                        && (conf->flag & flag_value))
                        fputs("\t*", pileup_fp);
                    flag_value <<= 1;
                }
                if (conf->auxlist) {
                    int t = 0;
                    while(t++ < ((klist_t(auxlist) *)conf->auxlist)->size)
                        fputs("\t*", pileup_fp);
                }
            } else {
                if (ks_seq.l) {
                    fwrite(ks_seq.s, 1, ks_seq.l, pileup_fp);
                } else {
                    putc('*', pileup_fp);
                }
                putc('\t', pileup_fp);

                if (ks_qual.l) {
                    fwrite(ks_qual.s, 1, ks_qual.l, pileup_fp);
                } else {
                    putc('*', pileup_fp);
                }

                /* Print selected columns */
                int flag_value = MPLP_PRINT_MAPQ_CHAR;
                while(flag_value < MPLP_PRINT_LAST) {
                    if (flag_value != MPLP_PRINT_MODS
                        && (conf->flag & flag_value)) {
                        int n = 0;
                        putc('\t', pileup_fp);
                        for (j = 0; j < n_plp[i]; ++j) {
                            const bam_pileup1_t *p = &plp[i][j];
                            int c = p->qpos < p->b->core.l_qseq
                                ? bam_get_qual(p->b)[p->qpos]
                                : 0;
                            if ( c < conf->min_baseQ ) continue;
                            if (n > 0 && flag_value != MPLP_PRINT_MAPQ_CHAR) putc(',', pileup_fp);
                            n++;

                            switch (flag_value) {
                            case MPLP_PRINT_MAPQ_CHAR:
                                c = p->b->core.qual + 33;
                                if (c > 126) c = 126;
                                putc(c, pileup_fp);
                                break;
                            case MPLP_PRINT_QPOS:
                                // query position in current orientation
                                fprintf(pileup_fp, "%d", p->qpos + 1);
                                break;
                            case MPLP_PRINT_QPOS5: {
                                // query position in 5' to 3' orientation
                                int pos5 = bam_is_rev(p->b)
                                    ? p->b->core.l_qseq-p->qpos + p->is_del
                                    : p->qpos + 1;
                                fprintf(pileup_fp, "%d", pos5);
                                break;
                            }
                            case MPLP_PRINT_QNAME:
                                fputs(bam_get_qname(p->b), pileup_fp);
                                break;
                            case MPLP_PRINT_FLAG:
                                fprintf(pileup_fp, "%d", p->b->core.flag);
                                break;
                            case MPLP_PRINT_RNAME:
                                if (p->b->core.tid >= 0)
                                    fputs(sam_hdr_tid2name(h, p->b->core.tid), pileup_fp);
                                else
                                    putc('*', pileup_fp);
                                break;
                            case MPLP_PRINT_POS:
                                fprintf(pileup_fp, "%"PRId64, (int64_t) p->b->core.pos + 1);
                                break;
                            case MPLP_PRINT_MAPQ:
                                fprintf(pileup_fp, "%d", p->b->core.qual);
                                break;
                            case MPLP_PRINT_RNEXT:
                                if (p->b->core.mtid >= 0)
                                    fputs(sam_hdr_tid2name(h, p->b->core.mtid), pileup_fp);
                                else
                                    putc('*', pileup_fp);
                                break;
                            case MPLP_PRINT_PNEXT:
                                fprintf(pileup_fp, "%"PRId64, (int64_t) p->b->core.mpos + 1);
                                break;
                            case MPLP_PRINT_RLEN:
                                fprintf(pileup_fp, "%d", p->b->core.l_qseq);
                                break;
                            }
                        }
                        if (!n) putc('*', pileup_fp);
                    }
                    flag_value <<= 1;
                }

                /* Print selected tags */
                klist_t(auxlist) *auxlist_p = ((klist_t(auxlist) *)conf->auxlist);
                if (auxlist_p && auxlist_p->size) {
                    kliter_t(auxlist) *aux;
                    for (aux = kl_begin(auxlist_p); aux != kl_end(auxlist_p); aux = kl_next(aux)) {
                        int n = 0; // NB shadows outer loop
                        putc('\t', pileup_fp);
                        for (j = 0; j < n_plp[i]; ++j) {
                            const bam_pileup1_t *p = &plp[i][j];
                            int c = p->qpos < p->b->core.l_qseq
                                ? bam_get_qual(p->b)[p->qpos]
                                : 0;
                            if ( c < conf->min_baseQ ) continue;

                            if (n > 0) putc(conf->sep, pileup_fp);
                            n++;
                            uint8_t* tag_u = bam_aux_get(p->b, kl_val(aux));
                            if (!tag_u) {
                                putc(conf->empty , pileup_fp);
                                continue;
                            }

                            int tag_supported = 0;

                            /* Tag value is string */
                            if (*tag_u == 'Z' || *tag_u == 'H') {
                                char *tag_s = bam_aux2Z(tag_u);
                                if (!tag_s) continue;
                                fputs(tag_s, pileup_fp);
                                tag_supported = 1;
                            }

                            /* Tag value is integer */
                            if (*tag_u == 'I' || *tag_u == 'i' || *tag_u == 'C' || *tag_u == 'c' || *tag_u == 'S' || *tag_u == 's') {
                                int64_t tag_i = bam_aux2i(tag_u);
                                fprintf(pileup_fp, "%" PRId64 "", tag_i);
                                tag_supported = 1;
                            }

                            /* Tag value is float */
                            if (*tag_u == 'd' || *tag_u == 'f') {
                                double tag_f = bam_aux2f(tag_u);
                                fprintf(pileup_fp, "%lf", tag_f);
                                tag_supported = 1;
                            }

                            /* Tag value is character */
                            if (*tag_u == 'A') {
                                char tag_c = bam_aux2A(tag_u);
                                putc(tag_c, pileup_fp);
                                tag_supported = 1;
                            }

                            if (!tag_supported) putc('*', pileup_fp);
                        }
                        if (!n) putc('*', pileup_fp);
                    }
                }
            }
        }
        putc('\n', pileup_fp);
    }

    ks_free(&ks_seq);
    ks_free(&ks_mod);
    ks_free(&ks_qual);

    if (ret < 0) {
        print_error("mpileup", "error reading from input file");
        ret = EXIT_FAILURE;
        goto fail;
    }

    if (conf->all) {
        // Handle terminating region
        if (last_tid < 0 && conf->reg && conf->all > 1) {
            last_tid = tid0;
            last_pos = beg0-1;
            mplp_get_ref(data[0], tid0, &ref, &ref_len);
        } else if (last_tid < 0 && !one_seq && conf->all > 1) {
            last_tid = 0; // --aa on a blank file
        }
        while (last_tid >= 0 && last_tid < sam_hdr_nref(h)) {
            mplp_get_ref(data[0], last_tid, &ref, &ref_len);
            while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                if (last_pos >= end0) break;
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0)
                    continue;
                print_empty_pileup(pileup_fp, conf, sam_hdr_tid2name(h, last_tid), last_pos, nfn, ref, ref_len);
            }
            last_tid++;
            last_pos = -1;
            if (conf->all < 2 || conf->reg)
                break;
        }
    }

fail:
    // clean up
    if (pileup_fp && conf->output_fname) fclose(pileup_fp);
    bam_smpl_destroy(sm); free(buf.s);
    for (i = 0; i < gplp.n; ++i) free(gplp.plp[i]);
    free(gplp.plp); free(gplp.n_plp); free(gplp.m_plp);
    bam_mplp_destroy(iter);
    sam_hdr_destroy(h);
    for (i = 0; i < nfn; ++i) {
        sam_close(data[i]->fp);
        if (data[i]->iter) hts_itr_destroy(data[i]->iter);
        free(data[i]);
    }
    free(data); free(plp); free(n_plp);
    free(mp_ref.ref[0]);
    free(mp_ref.ref[1]);
    free(mp_ref.ref[2]);
    return ret;
}

__be32
do_nfsd_create(struct svc_rqst *rqstp, struct svc_fh *fhp,
		char *fname, int flen, struct iattr *iap,
		struct svc_fh *resfhp, int createmode, u32 *verifier,
	        bool *truncp, bool *created)
{
	struct dentry	*dentry, *dchild = NULL;
	struct inode	*dirp;
	__be32		err;
	int		host_err;
	__u32		v_mtime=0, v_atime=0;

	err = nfserr_perm;
	if (!flen)
		goto out;
	err = nfserr_exist;
	if (isdotent(fname, flen))
		goto out;
	if (!(iap->ia_valid & ATTR_MODE))
		iap->ia_mode = 0;
	err = fh_verify(rqstp, fhp, S_IFDIR, NFSD_MAY_EXEC);
	if (err)
		goto out;

	dentry = fhp->fh_dentry;
	dirp = d_inode(dentry);

	host_err = fh_want_write(fhp);
	if (host_err)
		goto out_nfserr;

	fh_lock_nested(fhp, I_MUTEX_PARENT);

	/*
	 * Compose the response file handle.
	 */
	dchild = lookup_one_len(fname, dentry, flen);
	host_err = PTR_ERR(dchild);
	if (IS_ERR(dchild))
		goto out_nfserr;

	/* If file doesn't exist, check for permissions to create one */
	if (d_really_is_negative(dchild)) {
		err = fh_verify(rqstp, fhp, S_IFDIR, NFSD_MAY_CREATE);
		if (err)
			goto out;
	}

	err = fh_compose(resfhp, fhp->fh_export, dchild, fhp);
	if (err)
		goto out;

	if (nfsd_create_is_exclusive(createmode)) {
		/* solaris7 gets confused (bugid 4218508) if these have
		 * the high bit set, so just clear the high bits. If this is
		 * ever changed to use different attrs for storing the
		 * verifier, then do_open_lookup() will also need to be fixed
		 * accordingly.
		 */
		v_mtime = verifier[0]&0x7fffffff;
		v_atime = verifier[1]&0x7fffffff;
	}

	if (d_really_is_positive(dchild)) {
		err = 0;

		switch (createmode) {
		case NFS3_CREATE_UNCHECKED:
			if (! d_is_reg(dchild))
				goto out;
			else if (truncp) {
				/* in nfsv4, we need to treat this case a little
				 * differently.  we don't want to truncate the
				 * file now; this would be wrong if the OPEN
				 * fails for some other reason.  furthermore,
				 * if the size is nonzero, we should ignore it
				 * according to spec!
				 */
				*truncp = (iap->ia_valid & ATTR_SIZE) && !iap->ia_size;
			}
			else {
				iap->ia_valid &= ATTR_SIZE;
				goto set_attr;
			}
			break;
		case NFS3_CREATE_EXCLUSIVE:
			if (   d_inode(dchild)->i_mtime.tv_sec == v_mtime
			    && d_inode(dchild)->i_atime.tv_sec == v_atime
			    && d_inode(dchild)->i_size  == 0 ) {
				if (created)
					*created = true;
				break;
			}
			/* fall through */
		case NFS4_CREATE_EXCLUSIVE4_1:
			if (   d_inode(dchild)->i_mtime.tv_sec == v_mtime
			    && d_inode(dchild)->i_atime.tv_sec == v_atime
			    && d_inode(dchild)->i_size  == 0 ) {
				if (created)
					*created = true;
				goto set_attr;
			}
			/* fall through */
		case NFS3_CREATE_GUARDED:
			err = nfserr_exist;
		}
		fh_drop_write(fhp);
		goto out;
	}

	host_err = vfs_create(dirp, dchild, iap->ia_mode, true);
	if (host_err < 0) {
		fh_drop_write(fhp);
		goto out_nfserr;
	}
	if (created)
		*created = true;

	nfsd_check_ignore_resizing(iap);

	if (nfsd_create_is_exclusive(createmode)) {
		/* Cram the verifier into atime/mtime */
		iap->ia_valid = ATTR_MTIME|ATTR_ATIME
			| ATTR_MTIME_SET|ATTR_ATIME_SET;
		/* XXX someone who knows this better please fix it for nsec */ 
		iap->ia_mtime.tv_sec = v_mtime;
		iap->ia_atime.tv_sec = v_atime;
		iap->ia_mtime.tv_nsec = 0;
		iap->ia_atime.tv_nsec = 0;
	}

 set_attr:
	err = nfsd_create_setattr(rqstp, resfhp, iap);

	/*
	 * nfsd_create_setattr already committed the child
	 * (and possibly also the parent).
	 */
	if (!err)
		err = nfserrno(commit_metadata(fhp));

	/*
	 * Update the filehandle to get the new inode info.
	 */
	if (!err)
		err = fh_update(resfhp);

 out:
	fh_unlock(fhp);
	if (dchild && !IS_ERR(dchild))
		dput(dchild);
	fh_drop_write(fhp);
 	return err;

 out_nfserr:
	err = nfserrno(host_err);
	goto out;
}

