			t = afs_page_dirty_to(page, priv);
			if (f != 0 && !new_content) {
				unlock_page(page);
				put_page(page);
				break;
			}

			len += filler + t;
			filler = psize - t;
			if (len >= max_len || *_count <= 0)
				stop = true;
			else if (t == psize || new_content)
				stop = false;

			index += thp_nr_pages(page);
			if (!pagevec_add(&pvec, page))
				break;
			if (stop)
				break;
		}

		if (!stop)
			xas_pause(&xas);
		rcu_read_unlock();

		/* Now, if we obtained any pages, we can shift them to being
		 * writable and mark them for caching.
		 */
		if (!pagevec_count(&pvec))
			break;

		for (i = 0; i < pagevec_count(&pvec); i++) {
			page = pvec.pages[i];
			trace_afs_page_dirty(vnode, tracepoint_string("store+"), page);

			if (!clear_page_dirty_for_io(page))
				BUG();
			if (test_set_page_writeback(page))
				BUG();

			*_count -= thp_nr_pages(page);
			unlock_page(page);
		}

		pagevec_release(&pvec);
		cond_resched();
	} while (!stop);

	*_len = len;
}

void gmm_state_exception(ogs_fsm_t *s, amf_event_t *e)
{
    int xact_count = 0, r;
    ogs_nas_5gmm_cause_t gmm_cause;

    amf_ue_t *amf_ue = NULL;
    amf_sess_t *sess = NULL;
    ran_ue_t *ran_ue = NULL;
    ogs_nas_5gs_message_t *nas_message = NULL;
    ogs_nas_security_header_type_t h;
    ogs_sbi_message_t *sbi_message = NULL;

    ogs_assert(s);
    ogs_assert(e);

    amf_sm_debug(e);

    sess = amf_sess_find_by_id(e->sess_id);
    if (sess) {
        amf_ue = amf_ue_find_by_id(sess->amf_ue_id);
        ogs_assert(amf_ue);
    } else {
        amf_ue = amf_ue_find_by_id(e->amf_ue_id);
        ogs_assert(amf_ue);
    }

    switch (e->h.id) {
    case OGS_FSM_ENTRY_SIG:
        AMF_UE_CLEAR_PAGING_INFO(amf_ue);
        AMF_UE_CLEAR_N2_TRANSFER(amf_ue, pdu_session_resource_setup_request);
        AMF_UE_CLEAR_5GSM_MESSAGE(amf_ue);
        CLEAR_AMF_UE_ALL_TIMERS(amf_ue);

        if (amf_ue->amf_ue_context_transfer_state == UE_CONTEXT_TRANSFER_NEW_AMF_STATE) {
            /*
            * UE context transfer message has been sent
            * to old AMF after Registration request.
            * Now Registrations status update needs to be sent.
            */
            ogs_sbi_discovery_option_t *discovery_option = NULL;
            ogs_guami_t guami;
            int state = e->h.sbi.state;

            discovery_option = ogs_sbi_discovery_option_new();
            ogs_assert(discovery_option);

            memcpy(&guami.plmn_id, &amf_ue->home_plmn_id,
                    sizeof(ogs_plmn_id_t));
            memcpy(&guami.amf_id, &amf_ue->old_guti.amf_id,
                    sizeof(ogs_amf_id_t));

            ogs_sbi_discovery_option_set_guami(discovery_option, &guami);

            r = amf_ue_sbi_discover_and_send(
                    OGS_SBI_SERVICE_TYPE_NAMF_COMM, discovery_option,
                    amf_namf_comm_build_registration_status_update,
                    amf_ue, state,
                    (void *)OpenAPI_ue_context_transfer_status_NOT_TRANSFERRED);
            ogs_expect(r == OGS_OK);
            ogs_assert(r != OGS_ERROR);

            amf_ue->amf_ue_context_transfer_state = REGISTRATION_STATUS_UPDATE_NEW_AMF_STATE;
            break;
        }

        xact_count = amf_sess_xact_count(amf_ue);

        amf_sbi_send_release_all_sessions(
                ran_ue_find_by_id(amf_ue->ran_ue_id), amf_ue,
                AMF_RELEASE_SM_CONTEXT_NO_STATE);

        if (!AMF_SESSION_RELEASE_PENDING(amf_ue) &&
            amf_sess_xact_count(amf_ue) == xact_count) {
            r = ngap_send_ran_ue_context_release_command(
                    ran_ue_find_by_id(amf_ue->ran_ue_id),
                    NGAP_Cause_PR_nas, NGAP_CauseNas_normal_release,
                    NGAP_UE_CTX_REL_UE_CONTEXT_REMOVE, 0);
            ogs_expect(r == OGS_OK);
            ogs_assert(r != OGS_ERROR);
        }
        break;
    case OGS_FSM_EXIT_SIG:
        break;

    case AMF_EVENT_5GMM_MESSAGE:
        nas_message = e->nas.message;
        ogs_assert(nas_message);

        ran_ue = ran_ue_find_by_id(amf_ue->ran_ue_id);
        if (!ran_ue) {
            ogs_error("No NG Context SUPI[%s] NAS-Type[%d] "
                    "RAN-UE-ID[%d:%p]",
                    amf_ue->supi, nas_message->gmm.h.message_type,
                    amf_ue->ran_ue_id, ran_ue_find_by_id(amf_ue->ran_ue_id));
            ogs_assert(e->pkbuf);
            ogs_log_hexdump(OGS_LOG_ERROR, e->pkbuf->data, e->pkbuf->len);
            break;
        }

        h.type = e->nas.type;

        xact_count = amf_sess_xact_count(amf_ue);

        switch (nas_message->gmm.h.message_type) {
        case OGS_NAS_5GS_REGISTRATION_REQUEST:
            ogs_info("Registration request");
            gmm_cause = gmm_handle_registration_request(
                    amf_ue, h, e->ngap.code,
                    &nas_message->gmm.registration_request);
            if (gmm_cause != OGS_5GMM_CAUSE_REQUEST_ACCEPTED) {
                ogs_error("gmm_handle_registration_request() failed [%d]",
                            gmm_cause);
                r = nas_5gs_send_registration_reject(ran_ue, amf_ue, gmm_cause);
                ogs_expect(r == OGS_OK);
                ogs_assert(r != OGS_ERROR);
                OGS_FSM_TRAN(s, gmm_state_exception);
                break;
            }

            if (!AMF_UE_HAVE_SUCI(amf_ue)) {
                CLEAR_AMF_UE_TIMER(amf_ue->t3570);
                r = nas_5gs_send_identity_request(amf_ue);
                ogs_expect(r == OGS_OK);
                ogs_assert(r != OGS_ERROR);

                OGS_FSM_TRAN(s, &gmm_state_de_registered);
                break;
            }

            if (h.integrity_protected && SECURITY_CONTEXT_IS_VALID(amf_ue)) {

                /*
                 * If the OLD RAN_UE is being maintained in AMF-UE Context,
                 * it deletes the NG Context after exchanging
                 * the UEContextReleaseCommand/Complete with the gNB
                 */
                CLEAR_NG_CONTEXT(amf_ue);

                gmm_cause = gmm_handle_registration_update(
                        ran_ue, amf_ue, &nas_message->gmm.registration_request);
                if (gmm_cause != OGS_5GMM_CAUSE_REQUEST_ACCEPTED) {
                    ogs_error("[%s] gmm_handle_registration_update() "
                                "failed [%d]", amf_ue->suci, gmm_cause);
                    r = nas_5gs_send_registration_reject(
                            ran_ue, amf_ue, gmm_cause);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);
                    OGS_FSM_TRAN(s, gmm_state_exception);
                    break;
                }

                if (amf_sess_xact_count(amf_ue) == xact_count) {

                    if (amf_update_allowed_nssai(amf_ue) == false) {
                        ogs_error("No Allowed-NSSAI");
                        r = nas_5gs_send_gmm_reject(
                                ran_ue, amf_ue,
                                OGS_5GMM_CAUSE_NO_NETWORK_SLICES_AVAILABLE);
                        ogs_expect(r == OGS_OK);
                        ogs_assert(r != OGS_ERROR);
                        OGS_FSM_TRAN(s, gmm_state_exception);
                        break;
                    }

                    if (!PCF_AM_POLICY_ASSOCIATED(amf_ue)) {
                        r = amf_ue_sbi_discover_and_send(
                                OGS_SBI_SERVICE_TYPE_NPCF_AM_POLICY_CONTROL,
                                NULL,
                                amf_npcf_am_policy_control_build_create,
                                amf_ue, 0, NULL);
                        ogs_expect(r == OGS_OK);
                        ogs_assert(r != OGS_ERROR);
                        OGS_FSM_TRAN(s, &gmm_state_initial_context_setup);
                        break;
                    }

                    CLEAR_AMF_UE_TIMER(amf_ue->t3550);
                    r = nas_5gs_send_registration_accept(amf_ue);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);
                }

                if (amf_ue->next.m_tmsi)
                    OGS_FSM_TRAN(s, &gmm_state_initial_context_setup);
                else
                    OGS_FSM_TRAN(s, &gmm_state_registered);

            } else {

                amf_sbi_send_release_all_sessions(
                        ran_ue, amf_ue, AMF_RELEASE_SM_CONTEXT_NO_STATE);

                if (!AMF_SESSION_RELEASE_PENDING(amf_ue) &&
                    amf_sess_xact_count(amf_ue) == xact_count) {
                    r = amf_ue_sbi_discover_and_send(
                            OGS_SBI_SERVICE_TYPE_NAUSF_AUTH, NULL,
                            amf_nausf_auth_build_authenticate,
                            amf_ue, 0, NULL);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);
                }

                OGS_FSM_TRAN(s, &gmm_state_authentication);
            }
            break;

        default:
            ogs_error("Unknown message [%d]", nas_message->gmm.h.message_type);
        }
        break;
    case OGS_EVENT_SBI_CLIENT:
        sbi_message = e->h.sbi.message;
        ogs_assert(sbi_message);

        ran_ue_t *ran_ue = ran_ue_find_by_id(amf_ue->ran_ue_id);
        if (!ran_ue) {
            int i;
            ogs_error("No NG Context SUPI[%s] Status[%d] RAN-UE-ID[%d:%p]",
                    amf_ue->supi, sbi_message->res_status,
                    amf_ue->ran_ue_id, ran_ue_find_by_id(amf_ue->ran_ue_id));

            if (sbi_message->h.method)
                ogs_error("    h.method[%s]", sbi_message->h.method);
            if (sbi_message->h.uri)
                ogs_error("    h.uri[%s]", sbi_message->h.uri);
            if (sbi_message->h.service.name)
                ogs_error("    h.service.name[%s]",
                        sbi_message->h.service.name);
            if (sbi_message->h.api.version)
                ogs_error("    h.api.version[%s]", sbi_message->h.api.version);
            for (i = 0; i < OGS_SBI_MAX_NUM_OF_RESOURCE_COMPONENT &&
                        sbi_message->h.resource.component[i]; i++)
                ogs_error("    h.resource.component[%s:%d]",
                        sbi_message->h.resource.component[i], i);
            break;
        }

        SWITCH(sbi_message->h.service.name)
        CASE(OGS_SBI_SERVICE_NAME_NAUSF_AUTH)
            SWITCH(sbi_message->h.resource.component[0])
            CASE(OGS_SBI_RESOURCE_NAME_UE_AUTHENTICATIONS)

                if (sbi_message->res_status != OGS_SBI_HTTP_STATUS_CREATED &&
                    sbi_message->res_status != OGS_SBI_HTTP_STATUS_OK &&
                    sbi_message->res_status != OGS_SBI_HTTP_STATUS_NO_CONTENT) {
                    if (sbi_message->res_status ==
                            OGS_SBI_HTTP_STATUS_NOT_FOUND) {
                        ogs_warn("[%s] Cannot find SUCI [%d]",
                            amf_ue->suci, sbi_message->res_status);
                    } else {
                        ogs_error("[%s] HTTP response error [%d]",
                            amf_ue->suci, sbi_message->res_status);
                    }
                }

                SWITCH(sbi_message->h.method)
                CASE(OGS_SBI_HTTP_METHOD_POST)
                    ogs_warn("[%s] Ignore SBI message", amf_ue->suci);
                    break;
                CASE(OGS_SBI_HTTP_METHOD_PUT)
                    ogs_warn("[%s] Ignore SBI message", amf_ue->suci);
                    break;
                CASE(OGS_SBI_HTTP_METHOD_DELETE)
                    ogs_warn("[%s] Ignore SBI message", amf_ue->suci);
                    break;
                DEFAULT
                    ogs_error("[%s] Invalid HTTP method [%s]",
                            amf_ue->suci, sbi_message->h.method);
                    ogs_assert_if_reached();
                END
                break;

            CASE(OGS_SBI_RESOURCE_NAME_5G_AKA)
            CASE(OGS_SBI_RESOURCE_NAME_5G_AKA_CONFIRMATION)
            CASE(OGS_SBI_RESOURCE_NAME_EAP_SESSION)
                ogs_warn("[%s] Ignore SBI message", amf_ue->supi);
                break;

            DEFAULT
                ogs_error("Invalid resource name [%s]",
                        sbi_message->h.resource.component[0]);
                ogs_assert_if_reached();
            END
            break;

        CASE(OGS_SBI_SERVICE_NAME_NAMF_COMM)
            SWITCH(sbi_message->h.resource.component[0])
            CASE(OGS_SBI_RESOURCE_NAME_UE_CONTEXTS)
                SWITCH(sbi_message->h.resource.component[2])
                CASE(OGS_SBI_RESOURCE_NAME_TRANSFER_UPDATE)
                    if (amf_ue->amf_ue_context_transfer_state != REGISTRATION_STATUS_UPDATE_NEW_AMF_STATE) {
                        ogs_error("UE context transfer state not correct");
                    }
                    if (sbi_message->res_status != OGS_SBI_HTTP_STATUS_OK) {
                        ogs_error("[%s] HTTP response error [%d]",
                                amf_ue->supi, sbi_message->res_status);
                    }
                    r = amf_namf_comm_handle_registration_status_update_response(sbi_message, amf_ue);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);

                    amf_ue->amf_ue_context_transfer_state = UE_CONTEXT_INITIAL_STATE;

                    /* Continue with release command */
                    xact_count = amf_sess_xact_count(amf_ue);
                    amf_sbi_send_release_all_sessions(
                            ran_ue, amf_ue, AMF_RELEASE_SM_CONTEXT_NO_STATE);

                    if (!AMF_SESSION_RELEASE_PENDING(amf_ue) &&
                        amf_sess_xact_count(amf_ue) == xact_count) {
                        r = ngap_send_ran_ue_context_release_command(
                                ran_ue_find_by_id(amf_ue->ran_ue_id),
                                NGAP_Cause_PR_nas, NGAP_CauseNas_normal_release,
                                NGAP_UE_CTX_REL_UE_CONTEXT_REMOVE, 0);
                        ogs_expect(r == OGS_OK);
                        ogs_assert(r != OGS_ERROR);
                    }
                    break;

                DEFAULT
                    ogs_error("Invalid resource name [%s]",
                            sbi_message->h.resource.component[2]);
                    ogs_assert_if_reached();
                END
                break;

            DEFAULT
                ogs_error("Invalid resource name [%s]",
                        sbi_message->h.resource.component[0]);
                ogs_assert_if_reached();
            END
            break;

        DEFAULT
            ogs_error("Invalid service name [%s]", sbi_message->h.service.name);
            ogs_assert_if_reached();

        END
        break;

    default:
        ogs_error("Unknown event[%s]", amf_event_get_name(e));
    }
}

void gmm_state_exception(ogs_fsm_t *s, amf_event_t *e)
{
    int xact_count = 0, r;
    ogs_nas_5gmm_cause_t gmm_cause;

    amf_ue_t *amf_ue = NULL;
    amf_sess_t *sess = NULL;
    ran_ue_t *ran_ue = NULL;
    ogs_nas_5gs_message_t *nas_message = NULL;
    ogs_nas_security_header_type_t h;
    ogs_sbi_message_t *sbi_message = NULL;

    ogs_assert(s);
    ogs_assert(e);

    amf_sm_debug(e);

    sess = amf_sess_find_by_id(e->sess_id);
    if (sess) {
        amf_ue = amf_ue_find_by_id(sess->amf_ue_id);
        ogs_assert(amf_ue);
    } else {
        amf_ue = amf_ue_find_by_id(e->amf_ue_id);
        ogs_assert(amf_ue);
    }

    switch (e->h.id) {
    case OGS_FSM_ENTRY_SIG:
        AMF_UE_CLEAR_PAGING_INFO(amf_ue);
        AMF_UE_CLEAR_N2_TRANSFER(amf_ue, pdu_session_resource_setup_request);
        AMF_UE_CLEAR_5GSM_MESSAGE(amf_ue);
        CLEAR_AMF_UE_ALL_TIMERS(amf_ue);

        if (amf_ue->amf_ue_context_transfer_state == UE_CONTEXT_TRANSFER_NEW_AMF_STATE) {
            /*
            * UE context transfer message has been sent
            * to old AMF after Registration request.
            * Now Registrations status update needs to be sent.
            */
            ogs_sbi_discovery_option_t *discovery_option = NULL;
            ogs_guami_t guami;
            int state = e->h.sbi.state;

            discovery_option = ogs_sbi_discovery_option_new();
            ogs_assert(discovery_option);

            memcpy(&guami.plmn_id, &amf_ue->home_plmn_id,
                    sizeof(ogs_plmn_id_t));
            memcpy(&guami.amf_id, &amf_ue->old_guti.amf_id,
                    sizeof(ogs_amf_id_t));

            ogs_sbi_discovery_option_set_guami(discovery_option, &guami);

            r = amf_ue_sbi_discover_and_send(
                    OGS_SBI_SERVICE_TYPE_NAMF_COMM, discovery_option,
                    amf_namf_comm_build_registration_status_update,
                    amf_ue, state,
                    (void *)OpenAPI_ue_context_transfer_status_NOT_TRANSFERRED);
            ogs_expect(r == OGS_OK);
            ogs_assert(r != OGS_ERROR);

            amf_ue->amf_ue_context_transfer_state = REGISTRATION_STATUS_UPDATE_NEW_AMF_STATE;
            break;
        }

        xact_count = amf_sess_xact_count(amf_ue);

        amf_sbi_send_release_all_sessions(
                ran_ue_find_by_id(amf_ue->ran_ue_id), amf_ue,
                AMF_RELEASE_SM_CONTEXT_NO_STATE);

        if (!AMF_SESSION_RELEASE_PENDING(amf_ue) &&
            amf_sess_xact_count(amf_ue) == xact_count) {
            r = ngap_send_ran_ue_context_release_command(
                    ran_ue_find_by_id(amf_ue->ran_ue_id),
                    NGAP_Cause_PR_nas, NGAP_CauseNas_normal_release,
                    NGAP_UE_CTX_REL_UE_CONTEXT_REMOVE, 0);
            ogs_expect(r == OGS_OK);
            ogs_assert(r != OGS_ERROR);
        }
        break;
    case OGS_FSM_EXIT_SIG:
        break;

    case AMF_EVENT_5GMM_MESSAGE:
        nas_message = e->nas.message;
        ogs_assert(nas_message);

        ran_ue = ran_ue_find_by_id(amf_ue->ran_ue_id);
        if (!ran_ue) {
            ogs_error("No NG Context SUPI[%s] NAS-Type[%d] "
                    "RAN-UE-ID[%d:%p]",
                    amf_ue->supi, nas_message->gmm.h.message_type,
                    amf_ue->ran_ue_id, ran_ue_find_by_id(amf_ue->ran_ue_id));
            ogs_assert(e->pkbuf);
            ogs_log_hexdump(OGS_LOG_ERROR, e->pkbuf->data, e->pkbuf->len);
            break;
        }

        h.type = e->nas.type;

        xact_count = amf_sess_xact_count(amf_ue);

        switch (nas_message->gmm.h.message_type) {
        case OGS_NAS_5GS_REGISTRATION_REQUEST:
            ogs_info("Registration request");
            gmm_cause = gmm_handle_registration_request(
                    amf_ue, h, e->ngap.code,
                    &nas_message->gmm.registration_request);
            if (gmm_cause != OGS_5GMM_CAUSE_REQUEST_ACCEPTED) {
                ogs_error("gmm_handle_registration_request() failed [%d]",
                            gmm_cause);
                r = nas_5gs_send_registration_reject(ran_ue, amf_ue, gmm_cause);
                ogs_expect(r == OGS_OK);
                ogs_assert(r != OGS_ERROR);
                OGS_FSM_TRAN(s, gmm_state_exception);
                break;
            }

            if (!AMF_UE_HAVE_SUCI(amf_ue)) {
                CLEAR_AMF_UE_TIMER(amf_ue->t3570);
                r = nas_5gs_send_identity_request(amf_ue);
                ogs_expect(r == OGS_OK);
                ogs_assert(r != OGS_ERROR);

                OGS_FSM_TRAN(s, &gmm_state_de_registered);
                break;
            }

            if (h.integrity_protected && SECURITY_CONTEXT_IS_VALID(amf_ue)) {

                /*
                 * If the OLD RAN_UE is being maintained in AMF-UE Context,
                 * it deletes the NG Context after exchanging
                 * the UEContextReleaseCommand/Complete with the gNB
                 */
                CLEAR_NG_CONTEXT(amf_ue);

                gmm_cause = gmm_handle_registration_update(
                        ran_ue, amf_ue, &nas_message->gmm.registration_request);
                if (gmm_cause != OGS_5GMM_CAUSE_REQUEST_ACCEPTED) {
                    ogs_error("[%s] gmm_handle_registration_update() "
                                "failed [%d]", amf_ue->suci, gmm_cause);
                    r = nas_5gs_send_registration_reject(
                            ran_ue, amf_ue, gmm_cause);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);
                    OGS_FSM_TRAN(s, gmm_state_exception);
                    break;
                }

                if (amf_sess_xact_count(amf_ue) == xact_count) {

                    if (amf_update_allowed_nssai(amf_ue) == false) {
                        ogs_error("No Allowed-NSSAI");
                        r = nas_5gs_send_gmm_reject(
                                ran_ue, amf_ue,
                                OGS_5GMM_CAUSE_NO_NETWORK_SLICES_AVAILABLE);
                        ogs_expect(r == OGS_OK);
                        ogs_assert(r != OGS_ERROR);
                        OGS_FSM_TRAN(s, gmm_state_exception);
                        break;
                    }

                    if (!PCF_AM_POLICY_ASSOCIATED(amf_ue)) {
                        r = amf_ue_sbi_discover_and_send(
                                OGS_SBI_SERVICE_TYPE_NPCF_AM_POLICY_CONTROL,
                                NULL,
                                amf_npcf_am_policy_control_build_create,
                                amf_ue, 0, NULL);
                        ogs_expect(r == OGS_OK);
                        ogs_assert(r != OGS_ERROR);
                        OGS_FSM_TRAN(s, &gmm_state_initial_context_setup);
                        break;
                    }

                    CLEAR_AMF_UE_TIMER(amf_ue->t3550);
                    r = nas_5gs_send_registration_accept(amf_ue);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);
                }

                if (amf_ue->next.m_tmsi)
                    OGS_FSM_TRAN(s, &gmm_state_initial_context_setup);
                else
                    OGS_FSM_TRAN(s, &gmm_state_registered);

            } else {

                amf_sbi_send_release_all_sessions(
                        ran_ue, amf_ue, AMF_RELEASE_SM_CONTEXT_NO_STATE);

                if (!AMF_SESSION_RELEASE_PENDING(amf_ue) &&
                    amf_sess_xact_count(amf_ue) == xact_count) {
                    r = amf_ue_sbi_discover_and_send(
                            OGS_SBI_SERVICE_TYPE_NAUSF_AUTH, NULL,
                            amf_nausf_auth_build_authenticate,
                            amf_ue, 0, NULL);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);
                }

                OGS_FSM_TRAN(s, &gmm_state_authentication);
            }
            break;

        default:
            ogs_error("Unknown message [%d]", nas_message->gmm.h.message_type);
        }
        break;
    case OGS_EVENT_SBI_CLIENT:
        sbi_message = e->h.sbi.message;
        ogs_assert(sbi_message);

        ran_ue_t *ran_ue = ran_ue_find_by_id(amf_ue->ran_ue_id);
        if (!ran_ue) {
            int i;
            ogs_error("No NG Context SUPI[%s] Status[%d] RAN-UE-ID[%d:%p]",
                    amf_ue->supi, sbi_message->res_status,
                    amf_ue->ran_ue_id, ran_ue_find_by_id(amf_ue->ran_ue_id));

            if (sbi_message->h.method)
                ogs_error("    h.method[%s]", sbi_message->h.method);
            if (sbi_message->h.uri)
                ogs_error("    h.uri[%s]", sbi_message->h.uri);
            if (sbi_message->h.service.name)
                ogs_error("    h.service.name[%s]",
                        sbi_message->h.service.name);
            if (sbi_message->h.api.version)
                ogs_error("    h.api.version[%s]", sbi_message->h.api.version);
            for (i = 0; i < OGS_SBI_MAX_NUM_OF_RESOURCE_COMPONENT &&
                        sbi_message->h.resource.component[i]; i++)
                ogs_error("    h.resource.component[%s:%d]",
                        sbi_message->h.resource.component[i], i);
            break;
        }

        SWITCH(sbi_message->h.service.name)
        CASE(OGS_SBI_SERVICE_NAME_NAUSF_AUTH)
            SWITCH(sbi_message->h.resource.component[0])
            CASE(OGS_SBI_RESOURCE_NAME_UE_AUTHENTICATIONS)

                if (sbi_message->res_status != OGS_SBI_HTTP_STATUS_CREATED &&
                    sbi_message->res_status != OGS_SBI_HTTP_STATUS_OK &&
                    sbi_message->res_status != OGS_SBI_HTTP_STATUS_NO_CONTENT) {
                    if (sbi_message->res_status ==
                            OGS_SBI_HTTP_STATUS_NOT_FOUND) {
                        ogs_warn("[%s] Cannot find SUCI [%d]",
                            amf_ue->suci, sbi_message->res_status);
                    } else {
                        ogs_error("[%s] HTTP response error [%d]",
                            amf_ue->suci, sbi_message->res_status);
                    }
                }

                SWITCH(sbi_message->h.method)
                CASE(OGS_SBI_HTTP_METHOD_POST)
                    ogs_warn("[%s] Ignore SBI message", amf_ue->suci);
                    break;
                CASE(OGS_SBI_HTTP_METHOD_PUT)
                    ogs_warn("[%s] Ignore SBI message", amf_ue->suci);
                    break;
                CASE(OGS_SBI_HTTP_METHOD_DELETE)
                    ogs_warn("[%s] Ignore SBI message", amf_ue->suci);
                    break;
                DEFAULT
                    ogs_error("[%s] Invalid HTTP method [%s]",
                            amf_ue->suci, sbi_message->h.method);
                    ogs_assert_if_reached();
                END
                break;

            CASE(OGS_SBI_RESOURCE_NAME_5G_AKA)
            CASE(OGS_SBI_RESOURCE_NAME_5G_AKA_CONFIRMATION)
            CASE(OGS_SBI_RESOURCE_NAME_EAP_SESSION)
                ogs_warn("[%s] Ignore SBI message", amf_ue->supi);
                break;

            DEFAULT
                ogs_error("Invalid resource name [%s]",
                        sbi_message->h.resource.component[0]);
                ogs_assert_if_reached();
            END
            break;

        CASE(OGS_SBI_SERVICE_NAME_NUDM_UECM)
            SWITCH(sbi_message->h.resource.component[1])
            CASE(OGS_SBI_RESOURCE_NAME_REGISTRATIONS)
                if (sbi_message->res_status != OGS_SBI_HTTP_STATUS_CREATED &&
                    sbi_message->res_status != OGS_SBI_HTTP_STATUS_OK &&
                    sbi_message->res_status != OGS_SBI_HTTP_STATUS_NO_CONTENT) {
                    if (sbi_message->res_status ==
                            OGS_SBI_HTTP_STATUS_NOT_FOUND) {
                        ogs_warn("[%s] Cannot find SUCI [%d]",
                            amf_ue->suci, sbi_message->res_status);
                    } else {
                        ogs_error("[%s] HTTP response error [%d]",
                            amf_ue->suci, sbi_message->res_status);
                    }
                }

                SWITCH(sbi_message->h.method)
                CASE(OGS_SBI_HTTP_METHOD_PUT)
                    ogs_warn("[%s] Ignore SBI message", amf_ue->suci);
                    break;
                DEFAULT
                    ogs_error("[%s] Invalid HTTP method [%s]",
                            amf_ue->suci, sbi_message->h.method);
                    ogs_assert_if_reached();
                END
                break;

            DEFAULT
                ogs_error("Invalid resource name [%s]",
                        sbi_message->h.resource.component[1]);
                ogs_assert_if_reached();
            END
            break;

        CASE(OGS_SBI_SERVICE_NAME_NAMF_COMM)
            SWITCH(sbi_message->h.resource.component[0])
            CASE(OGS_SBI_RESOURCE_NAME_UE_CONTEXTS)
                SWITCH(sbi_message->h.resource.component[2])
                CASE(OGS_SBI_RESOURCE_NAME_TRANSFER_UPDATE)
                    if (amf_ue->amf_ue_context_transfer_state != REGISTRATION_STATUS_UPDATE_NEW_AMF_STATE) {
                        ogs_error("UE context transfer state not correct");
                    }
                    if (sbi_message->res_status != OGS_SBI_HTTP_STATUS_OK) {
                        ogs_error("[%s] HTTP response error [%d]",
                                amf_ue->supi, sbi_message->res_status);
                    }
                    r = amf_namf_comm_handle_registration_status_update_response(sbi_message, amf_ue);
                    ogs_expect(r == OGS_OK);
                    ogs_assert(r != OGS_ERROR);

                    amf_ue->amf_ue_context_transfer_state = UE_CONTEXT_INITIAL_STATE;

                    /* Continue with release command */
                    xact_count = amf_sess_xact_count(amf_ue);
                    amf_sbi_send_release_all_sessions(
                            ran_ue, amf_ue, AMF_RELEASE_SM_CONTEXT_NO_STATE);

                    if (!AMF_SESSION_RELEASE_PENDING(amf_ue) &&
                        amf_sess_xact_count(amf_ue) == xact_count) {
                        r = ngap_send_ran_ue_context_release_command(
                                ran_ue_find_by_id(amf_ue->ran_ue_id),
                                NGAP_Cause_PR_nas, NGAP_CauseNas_normal_release,
                                NGAP_UE_CTX_REL_UE_CONTEXT_REMOVE, 0);
                        ogs_expect(r == OGS_OK);
                        ogs_assert(r != OGS_ERROR);
                    }
                    break;

                DEFAULT
                    ogs_error("Invalid resource name [%s]",
                            sbi_message->h.resource.component[2]);
                    ogs_assert_if_reached();
                END
                break;

            DEFAULT
                ogs_error("Invalid resource name [%s]",
                        sbi_message->h.resource.component[0]);
                ogs_assert_if_reached();
            END
            break;

        DEFAULT
            ogs_error("Invalid service name [%s]", sbi_message->h.service.name);
            ogs_assert_if_reached();

        END
        break;

    default:
        ogs_error("Unknown event[%s]", amf_event_get_name(e));
    }
}

static void ip6addrlbl_putmsg(struct nlmsghdr *nlh,
			      int prefixlen, int ifindex, u32 lseq)
{
	struct ifaddrlblmsg *ifal = nlmsg_data(nlh);
	ifal->ifal_family = AF_INET6;
	ifal->ifal_prefixlen = prefixlen;
	ifal->ifal_flags = 0;
	ifal->ifal_index = ifindex;
	ifal->ifal_seq = lseq;
}

static void ip6addrlbl_putmsg(struct nlmsghdr *nlh,
			      int prefixlen, int ifindex, u32 lseq)
{
	struct ifaddrlblmsg *ifal = nlmsg_data(nlh);
	ifal->ifal_family = AF_INET6;
	ifal->__ifal_reserved = 0;
	ifal->ifal_prefixlen = prefixlen;
	ifal->ifal_flags = 0;
	ifal->ifal_index = ifindex;
	ifal->ifal_seq = lseq;
}

htp_status_t htp_gzip_decompressor_decompress(htp_decompressor_t *drec1, htp_tx_data_t *d) {
    size_t consumed = 0;
    int rc = 0;
    htp_status_t callback_rc;
    htp_decompressor_gzip_t *drec = (htp_decompressor_gzip_t*) drec1;

    // Pass-through the NULL chunk, which indicates the end of the stream.

    if (drec->super.passthrough) {
        htp_tx_data_t d2;
        d2.tx = d->tx;
        d2.data = d->data;
        d2.len = d->len;
        d2.is_last = d->is_last;

        callback_rc = drec->super.callback(&d2);
        if (callback_rc != HTP_OK) {
            return HTP_ERROR;
        }

        return HTP_OK;
    } else if (drec->zlib_initialized == HTP_COMPRESSION_OVER) {
        return HTP_ERROR;
    }

    if (d->data == NULL) {
        // Prepare data for callback.
        htp_tx_data_t dout;
        dout.tx = d->tx;
        // This is last call, so output uncompressed data so far
        dout.len = GZIP_BUF_SIZE - drec->stream.avail_out;
        if (dout.len > 0) {
            dout.data = drec->buffer;
        } else {
            dout.data = NULL;
        }
        dout.is_last = d->is_last;
        if (drec->super.next != NULL && drec->zlib_initialized) {
            return htp_gzip_decompressor_decompress(drec->super.next, &dout);
        } else {
            // Send decompressed data to the callback.
            callback_rc = drec->super.callback(&dout);
            if (callback_rc != HTP_OK) {
                htp_gzip_decompressor_end(drec);
                return callback_rc;
            }
        }

        return HTP_OK;
    }

restart:
    if (consumed > d->len || d->len > UINT32_MAX ) {
        htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_ERROR, 0, "GZip decompressor: consumed > d->len");
        return HTP_ERROR;
    }
    drec->stream.next_in = (unsigned char *) (d->data + consumed);
    drec->stream.avail_in = (uint32_t) (d->len - consumed);

    while (drec->stream.avail_in != 0) {
        // If there's no more data left in the
        // buffer, send that information out.
        if (drec->stream.avail_out == 0) {
            drec->crc = crc32(drec->crc, drec->buffer, GZIP_BUF_SIZE);

            // Prepare data for callback.
            htp_tx_data_t d2;
            d2.tx = d->tx;
            d2.data = drec->buffer;
            d2.len = GZIP_BUF_SIZE;
            d2.is_last = d->is_last;

            if (drec->super.next != NULL && drec->zlib_initialized) {
                callback_rc = htp_gzip_decompressor_decompress(drec->super.next, &d2);
            } else {
                // Send decompressed data to callback.
                callback_rc = drec->super.callback(&d2);
            }
            if (callback_rc != HTP_OK) {
                htp_gzip_decompressor_end(drec);
                return callback_rc;
            }

            drec->stream.next_out = drec->buffer;
            drec->stream.avail_out = GZIP_BUF_SIZE;
        }

        if (drec->zlib_initialized == HTP_COMPRESSION_LZMA) {
            if (drec->header_len < LZMA_PROPS_SIZE + 8) {
                consumed = LZMA_PROPS_SIZE + 8 - drec->header_len;
                if (consumed > drec->stream.avail_in) {
                    consumed = drec->stream.avail_in;
                }
                memcpy(drec->header + drec->header_len, drec->stream.next_in, consumed);
                drec->stream.next_in = (unsigned char *) (d->data + consumed);
                drec->stream.avail_in = (uint32_t) (d->len - consumed);
                drec->header_len += consumed;
            }
            if (drec->header_len == LZMA_PROPS_SIZE + 8) {
                rc = LzmaDec_Allocate(&drec->state, drec->header, LZMA_PROPS_SIZE, &lzma_Alloc);
                if (rc != SZ_OK)
                    return rc;
                LzmaDec_Init(&drec->state);
                // hacky to get to next step end retry allocate in case of failure
                drec->header_len++;
            }
            if (drec->header_len > LZMA_PROPS_SIZE + 8) {
                size_t inprocessed = drec->stream.avail_in;
                size_t outprocessed = drec->stream.avail_out;
                ELzmaStatus status;
                rc = LzmaDec_DecodeToBuf(&drec->state, drec->stream.next_out, &outprocessed,
                                          drec->stream.next_in, &inprocessed, LZMA_FINISH_ANY, &status, d->tx->cfg->lzma_memlimit);
                drec->stream.avail_in -= inprocessed;
                drec->stream.next_in += inprocessed;
                drec->stream.avail_out -= outprocessed;
                drec->stream.next_out += outprocessed;
                switch (rc) {
                    case SZ_OK:
                        rc = Z_OK;
                        if (status == LZMA_STATUS_FINISHED_WITH_MARK) {
                            rc = Z_STREAM_END;
                        }
                        break;
                    case SZ_ERROR_MEM:
                        htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_WARNING, 0, "LZMA decompressor: memory limit reached");
                        // fall through
                    default:
                        rc = Z_DATA_ERROR;
                }
            }
        } else if (drec->zlib_initialized) {
            rc = inflate(&drec->stream, Z_NO_FLUSH);
        } else {
            // no initialization means previous error on stream
            return HTP_ERROR;
        }
        int error_after_data = (rc == Z_DATA_ERROR && drec->restart == 0 && GZIP_BUF_SIZE > drec->stream.avail_out);
        if (rc == Z_STREAM_END || error_after_data) {
            // How many bytes do we have?
            size_t len = GZIP_BUF_SIZE - drec->stream.avail_out;

            // Update CRC

            // Prepare data for the callback.
            htp_tx_data_t d2;
            d2.tx = d->tx;
            d2.data = drec->buffer;
            d2.len = len;
            d2.is_last = d->is_last;

            if (drec->super.next != NULL && drec->zlib_initialized) {
                callback_rc = htp_gzip_decompressor_decompress(drec->super.next, &d2);
            } else {
                // Send decompressed data to the callback.
                callback_rc = drec->super.callback(&d2);
            }
            if (callback_rc != HTP_OK) {
                htp_gzip_decompressor_end(drec);
                return callback_rc;
            }
            drec->stream.avail_out = GZIP_BUF_SIZE;
            drec->stream.next_out = drec->buffer;
            // TODO Handle trailer.

            if (error_after_data) {
                // There is data even if there is an error
                // So use this data and log a warning
                htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_WARNING, 0, "GZip decompressor: inflate failed with %d", rc);
                drec->zlib_initialized = HTP_COMPRESSION_OVER;
                return HTP_ERROR;
            }
            return HTP_OK;
        }
        else if (rc != Z_OK) {
            htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_WARNING, 0, "GZip decompressor: inflate failed with %d", rc);
            if (drec->zlib_initialized == HTP_COMPRESSION_LZMA) {
                LzmaDec_Free(&drec->state, &lzma_Alloc);
                // so as to clean zlib ressources after restart
                drec->zlib_initialized = HTP_COMPRESSION_NONE;
            } else {
                inflateEnd(&drec->stream);
            }

            // see if we want to restart the decompressor
            if (htp_gzip_decompressor_restart(drec,
                                              d->data, d->len, &consumed) == 1)
            {
                // we'll be restarting the compressor
                goto restart;
            }

            drec->zlib_initialized = 0;

            // all our inflate attempts have failed, simply
            // pass the raw data on to the callback in case
            // it's not compressed at all

            htp_tx_data_t d2;
            d2.tx = d->tx;
            d2.data = d->data;
            d2.len = d->len;
            d2.is_last = d->is_last;

            callback_rc = drec->super.callback(&d2);
            if (callback_rc != HTP_OK) {
                return HTP_ERROR;
            }

            drec->stream.avail_out = GZIP_BUF_SIZE;
            drec->stream.next_out = drec->buffer;

            /* successfully passed through, lets continue doing that */
            drec->super.passthrough = 1;
            return HTP_OK;
        }
    }

    return HTP_OK;
}

htp_status_t htp_gzip_decompressor_decompress(htp_decompressor_t *drec1, htp_tx_data_t *d) {
    size_t consumed = 0;
    int rc = 0;
    htp_status_t callback_rc;
    htp_decompressor_gzip_t *drec = (htp_decompressor_gzip_t*) drec1;

    // Pass-through the NULL chunk, which indicates the end of the stream.

    if (drec->super.passthrough) {
        htp_tx_data_t d2;
        d2.tx = d->tx;
        d2.data = d->data;
        d2.len = d->len;
        d2.is_last = d->is_last;

        callback_rc = drec->super.callback(&d2);
        if (callback_rc != HTP_OK) {
            return HTP_ERROR;
        }

        return HTP_OK;
    } else if (drec->zlib_initialized == HTP_COMPRESSION_OVER) {
        return HTP_ERROR;
    }

    if (d->data == NULL) {
        // Prepare data for callback.
        htp_tx_data_t dout;
        dout.tx = d->tx;
        // This is last call, so output uncompressed data so far
        dout.len = GZIP_BUF_SIZE - drec->stream.avail_out;
        if (dout.len > 0) {
            dout.data = drec->buffer;
        } else {
            dout.data = NULL;
        }
        dout.is_last = d->is_last;
        if (drec->super.next != NULL && drec->zlib_initialized) {
            return htp_gzip_decompressor_decompress(drec->super.next, &dout);
        } else {
            // Send decompressed data to the callback.
            callback_rc = drec->super.callback(&dout);
            if (callback_rc != HTP_OK) {
                htp_gzip_decompressor_end(drec);
                return callback_rc;
            }
        }

        return HTP_OK;
    }

restart:
    if (consumed > d->len || d->len > UINT32_MAX ) {
        htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_ERROR, 0, "GZip decompressor: consumed > d->len");
        return HTP_ERROR;
    }
    drec->stream.next_in = (unsigned char *) (d->data + consumed);
    drec->stream.avail_in = (uint32_t) (d->len - consumed);

    while (drec->stream.avail_in != 0) {
        // If there's no more data left in the
        // buffer, send that information out.
        if (drec->stream.avail_out == 0) {
            drec->crc = crc32(drec->crc, drec->buffer, GZIP_BUF_SIZE);

            // Prepare data for callback.
            htp_tx_data_t d2;
            d2.tx = d->tx;
            d2.data = drec->buffer;
            d2.len = GZIP_BUF_SIZE;
            d2.is_last = d->is_last;

            if (drec->super.next != NULL && drec->zlib_initialized) {
                callback_rc = htp_gzip_decompressor_decompress(drec->super.next, &d2);
            } else {
                // Send decompressed data to callback.
                callback_rc = drec->super.callback(&d2);
            }
            if (callback_rc != HTP_OK) {
                htp_gzip_decompressor_end(drec);
                return callback_rc;
            }

            drec->stream.next_out = drec->buffer;
            drec->stream.avail_out = GZIP_BUF_SIZE;
        }

        if (drec->zlib_initialized == HTP_COMPRESSION_LZMA) {
            if (drec->header_len < LZMA_PROPS_SIZE + 8) {
                consumed = LZMA_PROPS_SIZE + 8 - drec->header_len;
                if (consumed > drec->stream.avail_in) {
                    consumed = drec->stream.avail_in;
                }
                memcpy(drec->header + drec->header_len, drec->stream.next_in, consumed);
                drec->stream.next_in = (unsigned char *) (d->data + consumed);
                drec->stream.avail_in = (uint32_t) (d->len - consumed);
                drec->header_len += consumed;
            }
            if (drec->header_len == LZMA_PROPS_SIZE + 8) {
                rc = LzmaDec_Allocate(&drec->state, drec->header, LZMA_PROPS_SIZE, &lzma_Alloc);
                if (rc != SZ_OK)
                    return rc;
                LzmaDec_Init(&drec->state);
                // hacky to get to next step end retry allocate in case of failure
                drec->header_len++;
            }
            if (drec->header_len > LZMA_PROPS_SIZE + 8) {
                size_t inprocessed = drec->stream.avail_in;
                size_t outprocessed = drec->stream.avail_out;
                ELzmaStatus status;
                rc = LzmaDec_DecodeToBuf(&drec->state, drec->stream.next_out, &outprocessed,
                                          drec->stream.next_in, &inprocessed, LZMA_FINISH_ANY, &status, d->tx->cfg->lzma_memlimit);
                drec->stream.avail_in -= inprocessed;
                drec->stream.next_in += inprocessed;
                drec->stream.avail_out -= outprocessed;
                drec->stream.next_out += outprocessed;
                switch (rc) {
                    case SZ_OK:
                        rc = Z_OK;
                        if (status == LZMA_STATUS_FINISHED_WITH_MARK) {
                            rc = Z_STREAM_END;
                        }
                        break;
                    case SZ_ERROR_MEM:
                        htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_WARNING, 0, "LZMA decompressor: memory limit reached");
                        // fall through
                    default:
                        rc = Z_DATA_ERROR;
                }
            }
        } else if (drec->zlib_initialized) {
            rc = inflate(&drec->stream, Z_NO_FLUSH);
        } else {
            // no initialization means previous error on stream
            return HTP_ERROR;
        }
        int error_after_data = (rc == Z_DATA_ERROR && drec->restart == 0 && GZIP_BUF_SIZE > drec->stream.avail_out);
        if (rc == Z_STREAM_END || error_after_data) {
            // How many bytes do we have?
            size_t len = GZIP_BUF_SIZE - drec->stream.avail_out;

            // Update CRC

            // Prepare data for the callback.
            htp_tx_data_t d2;
            d2.tx = d->tx;
            d2.data = drec->buffer;
            d2.len = len;
            d2.is_last = d->is_last;

            if (drec->super.next != NULL && drec->zlib_initialized) {
                callback_rc = htp_gzip_decompressor_decompress(drec->super.next, &d2);
            } else {
                // Send decompressed data to the callback.
                callback_rc = drec->super.callback(&d2);
            }
            if (callback_rc != HTP_OK) {
                htp_gzip_decompressor_end(drec);
                return callback_rc;
            }
            drec->stream.avail_out = GZIP_BUF_SIZE;
            drec->stream.next_out = drec->buffer;
            // TODO Handle trailer.

            if (error_after_data) {
                // There is data even if there is an error
                // So use this data and log a warning
                htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_WARNING, 0, "GZip decompressor: inflate failed with %d", rc);
                if (drec->zlib_initialized == HTP_COMPRESSION_LZMA) {
                    LzmaDec_Free(&drec->state, &lzma_Alloc);
                }
                drec->zlib_initialized = HTP_COMPRESSION_OVER;
                return HTP_ERROR;
            }
            return HTP_OK;
        }
        else if (rc != Z_OK) {
            htp_log(d->tx->connp, HTP_LOG_MARK, HTP_LOG_WARNING, 0, "GZip decompressor: inflate failed with %d", rc);
            if (drec->zlib_initialized == HTP_COMPRESSION_LZMA) {
                LzmaDec_Free(&drec->state, &lzma_Alloc);
                // so as to clean zlib ressources after restart
                drec->zlib_initialized = HTP_COMPRESSION_NONE;
            } else {
                inflateEnd(&drec->stream);
            }

            // see if we want to restart the decompressor
            if (htp_gzip_decompressor_restart(drec,
                                              d->data, d->len, &consumed) == 1)
            {
                // we'll be restarting the compressor
                goto restart;
            }

            drec->zlib_initialized = 0;

            // all our inflate attempts have failed, simply
            // pass the raw data on to the callback in case
            // it's not compressed at all

            htp_tx_data_t d2;
            d2.tx = d->tx;
            d2.data = d->data;
            d2.len = d->len;
            d2.is_last = d->is_last;

            callback_rc = drec->super.callback(&d2);
            if (callback_rc != HTP_OK) {
                return HTP_ERROR;
            }

            drec->stream.avail_out = GZIP_BUF_SIZE;
            drec->stream.next_out = drec->buffer;

            /* successfully passed through, lets continue doing that */
            drec->super.passthrough = 1;
            return HTP_OK;
        }
    }

    return HTP_OK;
}

static void update_or_create_fnhe(struct fib_nh_common *nhc, __be32 daddr,
				  __be32 gw, u32 pmtu, bool lock,
				  unsigned long expires)
{
	struct fnhe_hash_bucket *hash;
	struct fib_nh_exception *fnhe;
	struct rtable *rt;
	u32 genid, hval;
	unsigned int i;
	int depth;

	genid = fnhe_genid(dev_net(nhc->nhc_dev));
	hval = fnhe_hashfun(daddr);

	spin_lock_bh(&fnhe_lock);

	hash = rcu_dereference(nhc->nhc_exceptions);
	if (!hash) {
		hash = kcalloc(FNHE_HASH_SIZE, sizeof(*hash), GFP_ATOMIC);
		if (!hash)
			goto out_unlock;
		rcu_assign_pointer(nhc->nhc_exceptions, hash);
	}

	hash += hval;

	depth = 0;
	for (fnhe = rcu_dereference(hash->chain); fnhe;
	     fnhe = rcu_dereference(fnhe->fnhe_next)) {
		if (fnhe->fnhe_daddr == daddr)
			break;
		depth++;
	}

	if (fnhe) {
		if (fnhe->fnhe_genid != genid)
			fnhe->fnhe_genid = genid;
		if (gw)
			fnhe->fnhe_gw = gw;
		if (pmtu) {
			fnhe->fnhe_pmtu = pmtu;
			fnhe->fnhe_mtu_locked = lock;
		}
		fnhe->fnhe_expires = max(1UL, expires);
		/* Update all cached dsts too */
		rt = rcu_dereference(fnhe->fnhe_rth_input);
		if (rt)
			fill_route_from_fnhe(rt, fnhe);
		rt = rcu_dereference(fnhe->fnhe_rth_output);
		if (rt)
			fill_route_from_fnhe(rt, fnhe);
	} else {
		if (depth > FNHE_RECLAIM_DEPTH)
			fnhe = fnhe_oldest(hash);
		else {
			fnhe = kzalloc(sizeof(*fnhe), GFP_ATOMIC);
			if (!fnhe)
				goto out_unlock;

			fnhe->fnhe_next = hash->chain;
			rcu_assign_pointer(hash->chain, fnhe);
		}
		fnhe->fnhe_genid = genid;
		fnhe->fnhe_daddr = daddr;
		fnhe->fnhe_gw = gw;
		fnhe->fnhe_pmtu = pmtu;
		fnhe->fnhe_mtu_locked = lock;
		fnhe->fnhe_expires = max(1UL, expires);

		/* Exception created; mark the cached routes for the nexthop
		 * stale, so anyone caching it rechecks if this exception
		 * applies to them.
		 */
		rt = rcu_dereference(nhc->nhc_rth_input);
		if (rt)
			rt->dst.obsolete = DST_OBSOLETE_KILL;

		for_each_possible_cpu(i) {
			struct rtable __rcu **prt;

			prt = per_cpu_ptr(nhc->nhc_pcpu_rth_output, i);
			rt = rcu_dereference(*prt);
			if (rt)
				rt->dst.obsolete = DST_OBSOLETE_KILL;
		}
	}

	fnhe->fnhe_stamp = jiffies;

out_unlock:
	spin_unlock_bh(&fnhe_lock);
}

static void update_or_create_fnhe(struct fib_nh_common *nhc, __be32 daddr,
				  __be32 gw, u32 pmtu, bool lock,
				  unsigned long expires)
{
	struct fnhe_hash_bucket *hash;
	struct fib_nh_exception *fnhe;
	struct rtable *rt;
	u32 genid, hval;
	unsigned int i;
	int depth;

	genid = fnhe_genid(dev_net(nhc->nhc_dev));
	hval = fnhe_hashfun(daddr);

	spin_lock_bh(&fnhe_lock);

	hash = rcu_dereference(nhc->nhc_exceptions);
	if (!hash) {
		hash = kcalloc(FNHE_HASH_SIZE, sizeof(*hash), GFP_ATOMIC);
		if (!hash)
			goto out_unlock;
		rcu_assign_pointer(nhc->nhc_exceptions, hash);
	}

	hash += hval;

	depth = 0;
	for (fnhe = rcu_dereference(hash->chain); fnhe;
	     fnhe = rcu_dereference(fnhe->fnhe_next)) {
		if (fnhe->fnhe_daddr == daddr)
			break;
		depth++;
	}

	if (fnhe) {
		if (fnhe->fnhe_genid != genid)
			fnhe->fnhe_genid = genid;
		if (gw)
			fnhe->fnhe_gw = gw;
		if (pmtu) {
			fnhe->fnhe_pmtu = pmtu;
			fnhe->fnhe_mtu_locked = lock;
		}
		fnhe->fnhe_expires = max(1UL, expires);
		/* Update all cached dsts too */
		rt = rcu_dereference(fnhe->fnhe_rth_input);
		if (rt)
			fill_route_from_fnhe(rt, fnhe);
		rt = rcu_dereference(fnhe->fnhe_rth_output);
		if (rt)
			fill_route_from_fnhe(rt, fnhe);
	} else {
		/* Randomize max depth to avoid some side channels attacks. */
		int max_depth = FNHE_RECLAIM_DEPTH +
				prandom_u32_max(FNHE_RECLAIM_DEPTH);

		while (depth > max_depth) {
			fnhe_remove_oldest(hash);
			depth--;
		}

		fnhe = kzalloc(sizeof(*fnhe), GFP_ATOMIC);
		if (!fnhe)
			goto out_unlock;

		fnhe->fnhe_next = hash->chain;

		fnhe->fnhe_genid = genid;
		fnhe->fnhe_daddr = daddr;
		fnhe->fnhe_gw = gw;
		fnhe->fnhe_pmtu = pmtu;
		fnhe->fnhe_mtu_locked = lock;
		fnhe->fnhe_expires = max(1UL, expires);

		rcu_assign_pointer(hash->chain, fnhe);

		/* Exception created; mark the cached routes for the nexthop
		 * stale, so anyone caching it rechecks if this exception
		 * applies to them.
		 */
		rt = rcu_dereference(nhc->nhc_rth_input);
		if (rt)
			rt->dst.obsolete = DST_OBSOLETE_KILL;

		for_each_possible_cpu(i) {
			struct rtable __rcu **prt;

			prt = per_cpu_ptr(nhc->nhc_pcpu_rth_output, i);
			rt = rcu_dereference(*prt);
			if (rt)
				rt->dst.obsolete = DST_OBSOLETE_KILL;
		}
	}

	fnhe->fnhe_stamp = jiffies;

out_unlock:
	spin_unlock_bh(&fnhe_lock);
}

namespace hermes {
namespace vm {

/// StringView is a view to the string content from StringPrimitive.
/// It hides the difference between ASCII string and UTF16 string, and hence
/// allow you to iterate through a string without worrying about the type.
/// Internally, it's a char pointer and a char16 pointer (only one is valid).
///
/// Performance: Iterating from StringView is slighly slower than normal
/// iterations: every operation has one extra conditional check on the type.
/// If you are in a extremely performance sensitive setting, consider getting
/// raw pointers directly out of StringPrimitive and explicitly duplicate code
/// to handle char and char16 strings separately.
///
/// Alternatively, if you know the string is very likely to be UTF16, or the
/// string is short, consider call getUTF16Ref (which may invoke a string copy
/// if it turns out to be an ASCII string).
class StringView {
  friend class StringPrimitive;
  friend class IdentifierTable;

  union {
    /// StringView can be used to represent a view to a non-GC-managed string,
    /// a.k.a persistent identifiers whose string content is from a static
    /// memory address (either C++ literal or from a persistent bytecode module.
    const void *nonManagedStringPtr_;

    /// Handle pointing to the actual string. We need a handle to allow a
    /// StringView to survive allocations, so that we can have multiple
    /// StringViews around at the same time. Note that the StringPrimitive
    /// must have been resolved if it's a rope, i.e. we should be able to obtain
    /// a char/char16 pointer directly from str_.
    ///
    /// NOTE: we are using \c llvh::AlignedCharArrayUnion to avoid constructing
    /// the handle (which doesn't have a default constructor).
    llvh::AlignedCharArrayUnion<Handle<StringPrimitive>> strPrim_;
  };

  /// Starting index in the StringPrimitive as the beginning of this view.
  uint32_t startIndex_ : 30;

  /// Whether we are storing a handle or a non-managed pointer.
  uint32_t isHandle_ : 1;

  /// Whether the string is ASCII.
  uint32_t isASCII_ : 1;

  /// Length of the string.
  uint32_t length_;

 public:
  /// Iterator for StringView. It's mostly standard except *operator does not
  /// return a reference, which disables certain things such as creating a
  /// reverse_iterator using std::reverse_iterator.
  class const_iterator
      : public std::iterator<std::random_access_iterator_tag, char16_t> {
    friend class StringView;

    /// Current pointer position if the underlying string is char string.
    const char *charPtr_{nullptr};

    /// Current pointer position if the underlying string is char16 string.
    const char16_t *char16Ptr_{nullptr};

    const_iterator(const char *charPtr, const char16_t *char16Ptr)
        : charPtr_(charPtr), char16Ptr_(char16Ptr) {
      assert(
          ((!charPtr_) ^ (!char16Ptr_)) &&
          "Must provide one of char or char16 pointer");
    }

    explicit const_iterator(const char *ptr) : const_iterator(ptr, nullptr) {}

    explicit const_iterator(const char16_t *ptr)
        : const_iterator(nullptr, ptr) {}

   public:
    using difference_type = std::ptrdiff_t;
    using reference = char16_t;

    const_iterator() = default;

    /// Allows for copying.
    const_iterator(const const_iterator &other) = default;

    const_iterator &operator++() {
      if (charPtr_) {
        ++charPtr_;
      } else {
        ++char16Ptr_;
      }
      return *this;
    }
    const_iterator &operator--() {
      if (charPtr_) {
        --charPtr_;
      } else {
        --char16Ptr_;
      }
      return *this;
    }
    const_iterator &operator+=(difference_type rhs) {
      if (charPtr_) {
        charPtr_ += rhs;
      } else {
        char16Ptr_ += rhs;
      }
      return *this;
    }
    const_iterator &operator-=(difference_type rhs) {
      if (charPtr_) {
        charPtr_ -= rhs;
      } else {
        char16Ptr_ -= rhs;
      }
      return *this;
    }
    const_iterator operator++(int) {
      const_iterator tmp(charPtr_, char16Ptr_);
      if (charPtr_) {
        ++charPtr_;
      } else {
        ++char16Ptr_;
      }
      return tmp;
    }
    const_iterator operator--(int) {
      const_iterator tmp(charPtr_, char16Ptr_);
      if (charPtr_) {
        --charPtr_;
      } else {
        --char16Ptr_;
      }
      return tmp;
    }

    difference_type operator-(const const_iterator &rhs) const {
      if (charPtr_) {
        return charPtr_ - rhs.charPtr_;
      }
      return char16Ptr_ - rhs.char16Ptr_;
    }

    const_iterator operator-(difference_type rhs) const {
      if (charPtr_) {
        return const_iterator(charPtr_ - rhs, char16Ptr_);
      }
      return const_iterator(charPtr_, char16Ptr_ - rhs);
    }
    const_iterator operator+(difference_type rhs) const {
      if (charPtr_) {
        return const_iterator(charPtr_ + rhs, char16Ptr_);
      }
      return const_iterator(charPtr_, char16Ptr_ + rhs);
    }

    /// Const dereference. Note that we cannot return a reference here (without
    /// losing efficiency, and hence making this iterator non-standard.
    char16_t operator*() const {
      return charPtr_ ? *charPtr_ : *char16Ptr_;
    }

    /// Comparisons.
    bool operator==(const const_iterator &rhs) const {
      if (charPtr_) {
        return charPtr_ == rhs.charPtr_;
      }
      return char16Ptr_ == rhs.char16Ptr_;
    }
    bool operator!=(const const_iterator &rhs) const {
      return !(*this == rhs);
    }
    bool operator>(const const_iterator &rhs) const {
      if (charPtr_) {
        return charPtr_ > rhs.charPtr_;
      }
      return char16Ptr_ > rhs.char16Ptr_;
    }
    bool operator<(const const_iterator &rhs) const {
      if (charPtr_) {
        return charPtr_ < rhs.charPtr_;
      }
      return char16Ptr_ < rhs.char16Ptr_;
    }
    bool operator>=(const const_iterator &rhs) const {
      return !(*this < rhs);
    }
    bool operator<=(const const_iterator &rhs) const {
      return !(*this > rhs);
    }
  };

  /// Reverse iterator type.
  using const_reverse_iterator = std::reverse_iterator<const_iterator>;

// In debug mode the handle is non-trivial, which makes us non-trivial too and
// we need to invoke its copy constructor and destructor.
// We could also deal with this using templates, by inheriting from a different
// base class depending on std::is_trivially_copyable<>, but the complexity is
// probably not worth it.
#ifndef NDEBUG
  StringView(const StringView &other) {
    ::memcpy(this, &other, sizeof(*this));
    if (isHandle_)
      new (strPrim_.buffer) Handle<StringPrimitive>(other.strPrim());
  }

  StringView &operator=(const StringView &other) {
    if (this != &other) {
      if (isHandle_)
        strPrim().~Handle<StringPrimitive>();
      ::memcpy(this, &other, sizeof(*this));
      if (isHandle_)
        new (strPrim_.buffer) Handle<StringPrimitive>(other.strPrim());
    }
